parameters.jsCode:
// Parse & normalize the DrSnip custom-app Registration payload.
// Reads the clean JSON shape posted by the intake app (no JotForm rawRequest).
const raw = $input.first().json;
const body = raw.body || raw;

const patient = body.patient || {};
const consent = body.consent || {};
const medical = body.medicalHistory || {};
const insurance = body.insurance || {};

const phoneDigits = (patient.phone || '').replace(/\D/g, '');

// ----- Address resilience (2026-05-27 bridge-link patch) -----------------
// The custom-app form (artifacts/intake-form/src/pages/Home.tsx) currently
// captures Street Address as a single freeform textarea with placeholder
// "Street, city, ZIP" and a separate State field. The N8N_CUTOVER_NOTES
// §C.1 contract has separate city / postalCode / addressLine2 / country
// fields. When those structured fields aren't populated we defensively
// extract from the freeform blob so DrChrono Create Patient doesn't 400 on
// empty zip_code / city.
//
// Sentinels: when neither the structured field nor the regex extract finds
// a value, fall back to '00000' (zip) and 'Unspecified' (city). These are
// clearly bad data — they keep DrChrono happy (non-blank validation passes)
// while making it easy for an admin to identify rows that need a
// follow-up correction in the chart.
//
// HIPAA: address components are PHI in combination with other identifiers.
// We never log the extracted values.
function trimStr(v) { return typeof v === 'string' ? v.trim() : ''; }
function extractZip(blob) {
  if (!blob) return '';
  const m = String(blob).match(/\b(\d{5}(?:-\d{4})?)\b/);
  return m ? m[1] : '';
}
function extractCity(blob, zip, state) {
  if (!blob) return '';
  let s = String(blob);
  if (zip) s = s.replace(zip, '');
  if (state) {
    const escaped = state.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    s = s.replace(new RegExp('\\b' + escaped + '\\b', 'i'), '');
  }
  // Common shape: "<street>, <city>, <state> <zip>". After stripping zip
  // and state the last non-empty comma-separated chunk is usually the city.
  const parts = s.split(',').map((p) => p.trim()).filter(Boolean);
  if (parts.length >= 2) return parts[parts.length - 1];
  return '';
}

const streetBlob = trimStr(patient.streetAddress);
const directZip = trimStr(patient.postalCode);
const directCity = trimStr(patient.city);
const directState = trimStr(patient.state);
const directAddrLine2 = trimStr(patient.addressLine2);
const directCountry = trimStr(patient.country);

const extractedZip = directZip || extractZip(streetBlob);
const extractedCity = directCity || extractCity(streetBlob, extractedZip, directState);

// Final fallbacks for DrChrono's non-blank validation.
const finalZip = extractedZip || '00000';
const finalCity = extractedCity || 'Unspecified';

// Medical history in the Phase-3 (Jeff feedback) order.
const MEDICAL_ORDER = [
  ['mhMentalIllness', 'Does mental illness or depression affect your decision making?'],
  ['mhPainSensitive', 'Do you think you are more sensitive to pain than the average person?'],
  ['mhFainting', 'Have you ever fainted during, or after, a medical procedure?'],
  ['mhBleeding', 'Do you, or does anyone in your family, have a tendency to bleed easily?'],
  ['mhKidney', 'Do you have a kidney abnormality or abnormal kidney function?'],
  ['mhSTI', 'Have you ever had AIDS, Chlamydia, Epididymitis, Gonorrhea, Hepatitis, or Prostatitis?'],
  ['mhTesticleAbnormality', 'Have you ever had Testicle abnormality, scrotum abnormality, hernia, infection, or tumor?'],
  ['mhTesticleInjury', 'Have you ever had a serious injury to, or surgery of, the testicles or scrotal area?'],
  ['mhSurgeries', 'Have you had any surgeries?'],
  ['mhSurgyComplications', 'Have you had any complications or excessive pain or bleeding after surgery?'],
  ['mhMedications', 'Is there medication you take regularly or have you taken any medication in the last 2 weeks?'],
  ['mhAspirin', 'Are you currently taking any aspirin products, or anticipate taking aspirin in the five days leading up to your procedure?'],
  ['mhAllergies', 'Do you have any allergies to a drug, medication, or anesthetic?'],
  ['mhChronic', 'Have you had any major medical problems or do you have any chronic medical problems?'],
];

const medicalHistory = MEDICAL_ORDER.map(([key, label]) => {
  const m = medical[key] || {};
  return { key, label, answer: m.answer || '', details: m.details || '' };
});

const front = insurance.cardFront || null;
const back = insurance.cardBack || null;
const hasCards = !!(front && front.base64Data) || !!(back && back.base64Data);

return [{ json: {
  submission_id: body.submissionId || '',
  form_type: body.formType || 'registration',
  timestamp: body.submittedAt || new Date().toISOString(),
  source: 'custom-app-v2',

  first_name: patient.legalFirstName || '',
  last_name: patient.legalLastName || '',
  preferred_first_name: patient.preferredFirstName || '',
  middle_initial: patient.middleInitial || '',
  dob: patient.dateOfBirth || '',
  email: (patient.email || '').toLowerCase().trim(),
  phone: patient.phone || '',
  phone_digits: phoneDigits,

  address_line1: streetBlob,
  address_line2: directAddrLine2,
  address_city: finalCity,
  address_state: directState,
  address_zip: finalZip,
  address_country: directCountry,

  // Debug breadcrumb for the audit Sheet / admin console: did we have to
  // synthesize either field from the freeform blob (or fall back to sentinel)?
  address_extracted: !directZip || !directCity,
  address_zip_sentinel: !extractedZip,
  address_city_sentinel: !extractedCity,

  office_location: patient.officeLocation || '',
  primary_care_physician: patient.primaryCarePhysician || '',

  consent_voicemail_question: consent.voicemailQuestion || 'Do you give consent for DrSnip to leave voicemails at the number provided?',
  consent_voicemail_answer: consent.voicemail === true ? 'Yes' : (consent.voicemail === false ? 'No' : ''),
  consent_text_question: consent.textQuestion || 'Do you give consent for DrSnip to send text messages to the number provided?',
  consent_text_answer: consent.text === true ? 'Yes' : (consent.text === false ? 'No' : ''),

  medical_history: medicalHistory,
  mh_mental_illness: ((medical.mhMentalIllness || {}).answer) || '',

  insurance_status: insurance.status || '',
  insurance_provider: insurance.provider || '',
  insurance_member_id: insurance.memberId || '',
  insurance_group_id: insurance.groupId || '',

  has_insurance_cards: hasCards,
  insurance_card_front_b64: (front && front.base64Data) || '',
  insurance_card_front_mime: (front && front.contentType) || 'image/jpeg',
  insurance_card_front_filename: (front && front.filename) || '',
  insurance_card_back_b64: (back && back.base64Data) || '',
  insurance_card_back_mime: (back && back.contentType) || 'image/jpeg',
  insurance_card_back_filename: (back && back.filename) || ''
}}];

// Tighter duplicate detection than the original Registration workflow.
// DrChrono returns candidates matching name + DOB. We then require email OR
// digit-only phone to also match before treating it as the same patient. If
// nothing passes, or multiple pass, we route to manual review instead of
// silently overwriting an unrelated record.
const searchResp = $input.first().json;
const candidates = (searchResp && searchResp.results) || [];
const original = $('Parse & Normalize').first().json;

const wantedEmail = (original.email || '').toLowerCase().trim();
const wantedPhone = original.phone_digits || '';
const normPhone = (p) => (p || '').replace(/\D/g, '');

const scored = candidates.map((c) => {
  const cEmail = (c.email || '').toLowerCase().trim();
  const cPhone = normPhone(c.cell_phone || c.home_phone || c.office_phone || '');
  const emailOk = !!wantedEmail && cEmail === wantedEmail;
  const phoneOk = !!wantedPhone && cPhone === wantedPhone;
  return { id: c.id, email_match: emailOk, phone_match: phoneOk, pass: emailOk || phoneOk };
});

let match_outcome, match_reason, patient_id = null;
const candidate_count = candidates.length;
const passing = scored.filter((s) => s.pass);
let candidates_summary = '';

if (candidate_count === 0) {
  match_outcome = 'create';
  match_reason = 'no_candidates_create_new';
} else if (passing.length === 1) {
  match_outcome = 'update';
  match_reason = 'unique_disambiguated_match';
  patient_id = passing[0].id;
} else if (passing.length === 0) {
  match_outcome = 'manual_review';
  match_reason = candidate_count === 1 ? 'single_candidate_failed_disambiguation' : 'no_candidate_passed_disambiguation';
  candidates_summary = scored.map((s) => 'id=' + s.id).join(';');
} else {
  match_outcome = 'manual_review';
  match_reason = 'multiple_candidates_passed_disambiguation';
  candidates_summary = passing.map((s) => 'id=' + s.id).join(';');
}

return [{ json: {
  ...original,
  candidates_searched: candidate_count,
  passing_count: passing.length,
  candidates_summary,
  match_outcome,
  match_reason,
  patient_id
}}];

// Merge DrChrono response (Create or Update) with the original normalized payload.
const drchrono = $input.first().json;
const original = $('Parse & Normalize').first().json;
const disambig = $('Disambiguate Patient').first().json;

let patient_id = null;
let drchrono_action = null;

if (disambig.match_outcome === 'update') {
  // Update path — DrChrono PATCH may return an empty body; fall back to the
  // patient_id we already disambiguated.
  patient_id = disambig.patient_id || drchrono.id || null;
  drchrono_action = 'updated';
} else if (disambig.match_outcome === 'create') {
  patient_id = drchrono.id || null;
  drchrono_action = 'created';
}

return [{ json: { ...original, patient_id, drchrono_action } }];

// Generate doctor-friendly Registration Intake PDF (pure JS, no external deps).
// Mirrors the Phase 3 visual approved by Jeff: blue header band + DrSnip wordmark,
// large centered patient name, Age + DOB stat tiles, tabular medical record with
// rule separators between rows, full consent question text, footer on every
// page. HIPAA-safe — assembled in-process, never sent to a third-party renderer.
const data = $('Parse & Normalize').first().json;
const resolved = $input.first().json;

const PAGE_W = 612, PAGE_H = 792;
const ML = 54, MR = 54, MT = 54, MB = 54;
const FOOTER_RESERVE = 36;
const CONTENT_W = PAGE_W - ML - MR;
const LABEL_W = 196, COL_GAP = 12;
const VALUE_W = CONTENT_W - LABEL_W - COL_GAP;
const LABEL_SIZE = 9, VALUE_SIZE = 10;
const LABEL_LINE_H = 12, VALUE_LINE_H = 13;
const ROW_PAD_V = 4, ROW_MIN_H = 20;
const BAND_H = 80;

const C = {
  brand: [0x0f / 255, 0x4c / 255, 0x81 / 255],
  text: [0.12, 0.16, 0.22],
  muted: [0.42, 0.47, 0.53],
  faint: [0.62, 0.66, 0.70],
  line: [0.86, 0.88, 0.91],
  separator: [0xe5 / 255, 0xe7 / 255, 0xeb / 255],
  tile: [0.96, 0.97, 0.98],
  white: [1, 1, 1]
};

function charW(ch, font) {
  if (ch === ' ') return 0.28;
  if (ch === 'i' || ch === 'l' || ch === 'I' || ch === '.' || ch === ',' || ch === ';' || ch === ':' || ch === '!' || ch === "'" || ch === '|') return 0.30;
  if (ch >= 'A' && ch <= 'Z') return font === 'F2' ? 0.70 : 0.66;
  if (ch >= 'a' && ch <= 'z') return font === 'F2' ? 0.56 : 0.51;
  if (ch >= '0' && ch <= '9') return 0.56;
  if (ch === '(' || ch === ')' || ch === '-' || ch === '/' || ch === '[' || ch === ']') return 0.33;
  return font === 'F2' ? 0.56 : 0.51;
}
function tw(s, font, size) {
  let w = 0;
  const str = String(s == null ? '' : s);
  for (let i = 0; i < str.length; i++) w += charW(str[i], font);
  return w * size;
}

function wrap(text, font, size, maxWidth) {
  const out = [];
  const lines = String(text == null ? '' : text).split('\n');
  for (const rawLine of lines) {
    const words = rawLine.split(/\s+/).filter(Boolean);
    if (words.length === 0) { out.push(''); continue; }
    let line = '';
    for (const word of words) {
      let parts = [word];
      if (tw(word, font, size) > maxWidth) {
        parts = [];
        let rest = word;
        while (rest.length > 0) {
          let cut = rest.length;
          while (cut > 0 && tw(rest.slice(0, cut), font, size) > maxWidth) cut--;
          if (cut === 0) cut = 1;
          parts.push(rest.slice(0, cut));
          rest = rest.slice(cut);
        }
      }
      for (const piece of parts) {
        const candidate = line ? line + ' ' + piece : piece;
        if (line && tw(candidate, font, size) > maxWidth) {
          out.push(line);
          line = piece;
        } else {
          line = candidate;
        }
      }
    }
    if (line) out.push(line);
  }
  return out.length ? out : [''];
}

function pdfEsc(s) {
  return String(s == null ? '' : s)
    .replace(/\\/g, '\\\\')
    .replace(/\(/g, '\\(')
    .replace(/\)/g, '\\)')
    .replace(/—/g, '\\227')
    .replace(/–/g, '\\226')
    .replace(/’/g, '\\222')
    .replace(/‘/g, '\\221')
    .replace(/“/g, '\\223')
    .replace(/”/g, '\\224')
    .replace(/·/g, '\\267')
    .replace(/•/g, '\\225')
    .replace(/[\r\n]+/g, ' ')
    .replace(/[-￿]/g, '?');
}

const pages = [];
let curOps = [];
let y = PAGE_H - MT;

function newPage() {
  pages.push(curOps);
  curOps = [];
  y = PAGE_H - MT;
}
function ensure(needed) {
  if (y - needed < MB + FOOTER_RESERVE) newPage();
}
function emitText(text, x, yy, size, font, color) {
  curOps.push({ k: 't', text: text, x: x, y: yy, size: size, font: font, color: color });
}
function emitRect(x, yy, w, h, fill) {
  curOps.push({ k: 'r', x: x, y: yy, w: w, h: h, fill: fill });
}
function emitRectBorder(x, yy, w, h, fill, stroke) {
  curOps.push({ k: 'rb', x: x, y: yy, w: w, h: h, fill: fill, stroke: stroke });
}
function emitLine(x1, y1, x2, y2, color, width) {
  curOps.push({ k: 'l', x1: x1, y1: y1, x2: x2, y2: y2, color: color, width: width });
}

function renderHeader(opts) {
  const bandY = PAGE_H - BAND_H;
  emitRect(0, bandY, PAGE_W, BAND_H, C.brand);
  emitText('DrSnip', ML, bandY + BAND_H / 2 - 9, 22, 'F2', C.white);
  const badge = opts.formType === 'consultation' ? 'Consultation Intake' : 'Registration Intake';
  const bw = tw(badge, 'F2', 11);
  emitText(badge, PAGE_W - MR - bw, bandY + BAND_H / 2 - 5, 11, 'F2', C.white);

  y = bandY - 30;
  const nw = tw(opts.patientName, 'F2', 24);
  emitText(opts.patientName, (PAGE_W - nw) / 2, y - 24, 24, 'F2', C.text);
  y -= 24 + 6;

  if (opts.spouseName) {
    const sLabel = 'Spouse: ' + opts.spouseName;
    const sw = tw(sLabel, 'F3', 12);
    emitText(sLabel, (PAGE_W - sw) / 2, y - 12, 12, 'F3', C.muted);
    y -= 12 + 4;
  }
  y -= 16;

  const tiles = [{ label: 'AGE', value: opts.age != null ? String(opts.age) : '—' }];
  if (opts.formType === 'consultation') {
    tiles.push({ label: 'CHILDREN', value: opts.childCount != null ? String(opts.childCount) : '—' });
  }

  const TW = 156, TH = 56, TG = 16;
  const totalW = tiles.length * TW + (tiles.length - 1) * TG;
  let tx = (PAGE_W - totalW) / 2;
  const tileTop = y;
  for (const t of tiles) {
    emitRectBorder(tx, tileTop - TH, TW, TH, C.tile, C.line);
    const lw = tw(t.label, 'F1', 8);
    emitText(t.label, tx + (TW - lw) / 2, tileTop - 19, 8, 'F1', C.muted);
    const vw = tw(t.value, 'F2', 17);
    emitText(t.value, tx + (TW - vw) / 2, tileTop - 44, 17, 'F2', C.brand);
    tx += TW + TG;
  }
  y = tileTop - TH - 18;

  emitText('Submitted: ' + opts.submittedAt, ML, y - 9, 9, 'F1', C.muted);
  y -= 13;
  emitText('Submission ID: ' + opts.submissionId, ML, y - 8, 8, 'F1', C.faint);
  y -= 14;

  emitLine(ML, y, PAGE_W - MR, y, C.line, 0.75);
  y -= 8;
}

function heading(title) {
  y -= 10;
  ensure(30 + 2 * ROW_MIN_H);
  emitRect(ML, y - 13, 3, 13, C.brand);
  emitText(title, ML + 9, y - 12, 12, 'F2', C.brand);
  y -= 17;
  emitLine(ML, y, PAGE_W - MR, y, C.line, 0.75);
  y -= 10;
}

function row(label, value, valueFont, valueColor, omitRule) {
  const labelLines = wrap(label, 'F1', LABEL_SIZE, LABEL_W);
  const valueLines = wrap(value, valueFont, VALUE_SIZE, VALUE_W);
  const contentH = Math.max(labelLines.length * LABEL_LINE_H, valueLines.length * VALUE_LINE_H);
  const rowH = Math.max(contentH + ROW_PAD_V * 2, ROW_MIN_H);
  ensure(rowH);
  const top = y;
  const valueX = ML + LABEL_W + COL_GAP;
  let ly = top - ROW_PAD_V - LABEL_SIZE;
  for (const ln of labelLines) {
    emitText(ln, ML, ly, LABEL_SIZE, 'F1', C.muted);
    ly -= LABEL_LINE_H;
  }
  let vy = top - ROW_PAD_V - VALUE_SIZE;
  for (const ln of valueLines) {
    emitText(ln, valueX, vy, VALUE_SIZE, valueFont, valueColor);
    vy -= VALUE_LINE_H;
  }
  if (!omitRule) {
    emitLine(ML, top - rowH, PAGE_W - MR, top - rowH, C.separator, 0.5);
  }
  y = top - rowH;
}

function kv(label, value) {
  const trimmed = (value != null && String(value).trim()) ? String(value).trim() : '—';
  const isEmpty = trimmed === '—';
  row(label, trimmed, isEmpty ? 'F1' : 'F2', isEmpty ? C.faint : C.text, false);
}

function mh(label, answer, explanation) {
  const a = (answer && String(answer).trim()) ? String(answer).trim() : '—';
  const isYes = a.toLowerCase() === 'yes';
  const isEmpty = a === '—';
  const hasExp = isYes && explanation && String(explanation).trim();
  row(label, a, 'F2', isEmpty ? C.faint : (isYes ? C.brand : C.text), hasExp);
  if (hasExp) {
    row('', String(explanation).trim(), 'F3', C.muted, false);
  }
}

function calcAge(dob) {
  if (!dob) return null;
  const d = new Date(dob + 'T00:00:00');
  if (isNaN(d.getTime())) return null;
  const t = new Date();
  let a = t.getFullYear() - d.getFullYear();
  const m = t.getMonth() - d.getMonth();
  if (m < 0 || (m === 0 && t.getDate() < d.getDate())) a--;
  return a < 0 ? 0 : a;
}

const patientName = ((data.first_name || '') + ' ' + (data.last_name || '')).trim() || '(Unknown Patient)';
const submittedAt = ((data.timestamp || '').slice(0, 16).replace('T', ' ')) + ' UTC';

renderHeader({
  formType: 'registration',
  patientName: patientName,
  spouseName: null,
  age: calcAge(data.dob),
  childCount: null,
  dob: data.dob,
  submittedAt: submittedAt,
  submissionId: data.submission_id || ''
});

const mhMap = {};
for (const m of (data.medical_history || [])) {
  if (m && m.key) mhMap[m.key] = m;
}
const mhA = function (key) { return (mhMap[key] || {}).answer || ''; };
const mhD = function (key) { return (mhMap[key] || {}).details || ''; };

heading('Patient Information');
kv('Legal First Name', data.first_name);
kv('Preferred First Name (if different)', data.preferred_first_name);
kv('Middle Initial', data.middle_initial);
kv('Legal Last Name', data.last_name);
kv('Date of Birth', data.dob);
kv('Office Location', data.office_location);

heading('Contact & Consent');
const streetFull = [data.address_line1, data.address_line2].filter(Boolean).join(', ');
kv('Street Address', streetFull);
kv('City', data.address_city);
kv('State', data.address_state);
kv('ZIP', data.address_zip);
kv('Mobile Number', data.phone);
kv('Email', data.email);
kv(data.consent_voicemail_question || 'Voicemail consent', data.consent_voicemail_answer);
kv(data.consent_text_question || 'Text consent', data.consent_text_answer);

heading('Medical History');
kv('Current Primary Care Physician (name and location)', data.primary_care_physician);
mh('Do you, or does anyone in your family, have a tendency to bleed easily?', mhA('mhBleeding'), mhD('mhBleeding'));
mh('Do you have a kidney abnormality or abnormal kidney function?', mhA('mhKidney'), mhD('mhKidney'));
mh('Have you ever had AIDS, Chlamydia, Epididymitis, Gonorrhea, Hepatitis, or Prostatitis?', mhA('mhSTI'), mhD('mhSTI'));
mh('Have you ever had a hernia or any abnormality, infection, or tumor of the testicle or scrotum?', mhA('mhTesticleAbnormality'), mhD('mhTesticleAbnormality'));
mh('Have you ever had a serious injury to, or surgery of, the testicles or scrotal area?', mhA('mhTesticleInjury'), mhD('mhTesticleInjury'));
mh('Have you had any surgeries?', mhA('mhSurgeries'), mhD('mhSurgeries'));
mh('Have you had any complications or excessive pain or bleeding after surgery?', mhA('mhSurgyComplications'), mhD('mhSurgyComplications'));
mh('Is there medication you take regularly or have you taken any medication in the last 2 weeks?', mhA('mhMedications'), mhD('mhMedications'));
mh('Are you currently taking, or do you plan to take in the 5 days before your procedure, any aspirin or aspirin-containing products? Examples include low-dose/baby aspirin, Excedrin, Ecotrin, Anacin, or Alka-Seltzer Original.', mhA('mhAspirin'), mhD('mhAspirin'));
mh('Do you have any allergies to a drug, medication, or anesthetic?', mhA('mhAllergies'), mhD('mhAllergies'));
mh('Have you had any major medical problems or do you have any chronic medical problems?', mhA('mhChronic'), mhD('mhChronic'));

heading('Insurance');
kv('Current insurance coverage', data.insurance_status);
kv('Insurance Company', data.insurance_provider);
kv('ID No.', data.insurance_member_id);
kv('Group No.', data.insurance_group_id);
kv('Insurance card — front', data.insurance_card_front_filename ? data.insurance_card_front_filename + ' (uploaded)' : '');
kv('Insurance card — back', data.insurance_card_back_filename ? data.insurance_card_back_filename + ' (uploaded)' : '');

if (curOps.length) {
  pages.push(curOps);
  curOps = [];
}

const totalPages = pages.length;
const subId = data.submission_id || '';
for (let idx = 0; idx < pages.length; idx++) {
  const ops = pages[idx];
  const fy = 30;
  ops.push({ k: 'l', x1: ML, y1: fy + 12, x2: PAGE_W - MR, y2: fy + 12, color: C.line, width: 0.5 });
  const left = (patientName && patientName !== '(Unknown Patient)') ? (patientName + ' · CONFIDENTIAL / PHI') : 'DrSnip Patient Intake — CONFIDENTIAL / PHI';
  const center = 'Page ' + (idx + 1) + ' of ' + totalPages;
  const right = 'Submission ' + subId;
  const cw = tw(center, 'F1', 7);
  const rw = tw(right, 'F1', 7);
  ops.push({ k: 't', text: left, x: ML, y: fy, size: 7, font: 'F1', color: C.faint });
  ops.push({ k: 't', text: center, x: (PAGE_W - cw) / 2, y: fy, size: 7, font: 'F1', color: C.faint });
  ops.push({ k: 't', text: right, x: PAGE_W - MR - rw, y: fy, size: 7, font: 'F1', color: C.faint });
}

function fmtColor(c) { return c[0].toFixed(3) + ' ' + c[1].toFixed(3) + ' ' + c[2].toFixed(3); }
function renderOps(ops) {
  let s = '';
  let curFill = null, curStroke = null, curLW = null;
  for (const op of ops) {
    if (op.k === 't') {
      const key = op.color.join(',');
      if (key !== curFill) { s += fmtColor(op.color) + ' rg\n'; curFill = key; }
      s += 'BT /' + op.font + ' ' + op.size + ' Tf ' + op.x.toFixed(2) + ' ' + op.y.toFixed(2) + ' Td (' + pdfEsc(op.text) + ') Tj ET\n';
    } else if (op.k === 'r') {
      const key = op.fill.join(',');
      if (key !== curFill) { s += fmtColor(op.fill) + ' rg\n'; curFill = key; }
      s += op.x.toFixed(2) + ' ' + op.y.toFixed(2) + ' ' + op.w.toFixed(2) + ' ' + op.h.toFixed(2) + ' re f\n';
    } else if (op.k === 'rb') {
      const fk = op.fill.join(',');
      if (fk !== curFill) { s += fmtColor(op.fill) + ' rg\n'; curFill = fk; }
      const sk = op.stroke.join(',');
      if (sk !== curStroke) { s += fmtColor(op.stroke) + ' RG\n'; curStroke = sk; }
      if (curLW !== 1) { s += '1 w\n'; curLW = 1; }
      s += op.x.toFixed(2) + ' ' + op.y.toFixed(2) + ' ' + op.w.toFixed(2) + ' ' + op.h.toFixed(2) + ' re B\n';
    } else if (op.k === 'l') {
      const sk = op.color.join(',');
      if (sk !== curStroke) { s += fmtColor(op.color) + ' RG\n'; curStroke = sk; }
      if (curLW !== op.width) { s += op.width + ' w\n'; curLW = op.width; }
      s += op.x1.toFixed(2) + ' ' + op.y1.toFixed(2) + ' m ' + op.x2.toFixed(2) + ' ' + op.y2.toFixed(2) + ' l S\n';
    }
  }
  return s;
}

const objects = [];
function addObj(s) { objects.push(s); return objects.length; }
const catalogId = addObj('PLACEHOLDER');
const pagesId = addObj('PLACEHOLDER');
const helvId = addObj('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');
const helvBoldId = addObj('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');
const helvOblId = addObj('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Oblique /Encoding /WinAnsiEncoding >>');

const pageIds = [];
for (const ops of pages) {
  const stream = renderOps(ops);
  const len = Buffer.byteLength(stream, 'binary');
  const streamId = addObj('<< /Length ' + len + ' >>\nstream\n' + stream + 'endstream');
  const pageObj = '<< /Type /Page /Parent ' + pagesId + ' 0 R /MediaBox [0 0 ' + PAGE_W + ' ' + PAGE_H + '] /Resources << /Font << /F1 ' + helvId + ' 0 R /F2 ' + helvBoldId + ' 0 R /F3 ' + helvOblId + ' 0 R >> >> /Contents ' + streamId + ' 0 R >>';
  pageIds.push(addObj(pageObj));
}
objects[catalogId - 1] = '<< /Type /Catalog /Pages ' + pagesId + ' 0 R >>';
objects[pagesId - 1] = '<< /Type /Pages /Count ' + pageIds.length + ' /Kids [' + pageIds.map(function (i) { return i + ' 0 R'; }).join(' ') + '] >>';

let pdf = '%PDF-1.4\n%\xE2\xE3\xCF\xD3\n';
const offsets = [];
for (let i = 0; i < objects.length; i++) {
  offsets.push(Buffer.byteLength(pdf, 'binary'));
  pdf += (i + 1) + ' 0 obj\n' + objects[i] + '\nendobj\n';
}
const xrefStart = Buffer.byteLength(pdf, 'binary');
pdf += 'xref\n0 ' + (objects.length + 1) + '\n0000000000 65535 f \n';
for (const off of offsets) pdf += String(off).padStart(10, '0') + ' 00000 n \n';
pdf += 'trailer\n<< /Size ' + (objects.length + 1) + ' /Root ' + catalogId + ' 0 R >>\nstartxref\n' + xrefStart + '\n%%EOF';

const buffer = Buffer.from(pdf, 'binary');
const safeLast = ((data.last_name || 'patient') + '').replace(/[^a-zA-Z0-9_-]+/g, '_');
const pid = resolved.patient_id || data.submission_id || 'unknown';
const fileName = 'registration_' + safeLast + '_' + pid + '.pdf';

return [{
  json: {
    patient_id: resolved.patient_id,
    drchrono_action: resolved.drchrono_action,
    pdf_filename: fileName
  },
  binary: {
    pdf: { data: buffer.toString('base64'), mimeType: 'application/pdf', fileName: fileName, fileExtension: 'pdf' }
  }
}];

// Decode the base64 insurance-card images from the custom-app payload into
// real binaries, one item per card present, so DrChrono: Upload Document can
// iterate them. No JotForm fetch needed.
const src = $('Parse & Normalize').first().json;
const patient_id = $('Resolve Patient ID').first().json.patient_id;
const submission_id = src.submission_id || 'submission';

const MIME_EXT = {
  'image/jpeg': 'jpg', 'image/jpg': 'jpg', 'image/png': 'png',
  'image/gif': 'gif', 'image/webp': 'webp', 'image/heic': 'heic',
  'application/pdf': 'pdf'
};

const out = [];
for (const side of ['front', 'back']) {
  const b64 = src[`insurance_card_${side}_b64`];
  if (!b64) continue;
  const mime = src[`insurance_card_${side}_mime`] || 'image/jpeg';
  const ext = MIME_EXT[mime] || 'jpg';
  const filename = src[`insurance_card_${side}_filename`] || `insurance_card_${side}_${submission_id}.${ext}`;
  out.push({
    json: { patient_id, submission_id, card_side: side, document_type: `insurance_card_${side}` },
    binary: {
      data: { data: b64, mimeType: mime, fileName: filename, fileExtension: ext }
    }
  });
}
return out;

